// Package memory stores memories: durable, source-backed
// knowledge derived from raw events. In v0.1 they are generated by rules
// (see summary.Memories); every memory keeps references to the events and
// sessions it came from.
package memory

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/chux0519/memspace/internal/evidence"
	"github.com/chux0519/memspace/internal/model"
	"github.com/chux0519/memspace/internal/search"
)

// Types and statuses.
const (
	TypeEpisodic   = "episodic"
	TypeProcedural = "procedural"

	StatusCandidate = "candidate"
)

// SourceRef points at what a memory was derived from.
type SourceRef struct {
	Kind string `json:"kind"` // event | session
	ID   string `json:"id"`
}

// Memory is one stored memory.
type Memory struct {
	ID          string      `json:"memory_id"`
	ProjectID   string      `json:"project_id"`
	ProjectName string      `json:"project_name,omitempty"`
	SessionID   string      `json:"session_id,omitempty"`
	DedupKey    string      `json:"-"`
	Scope       string      `json:"scope"`
	Type        string      `json:"type"`
	Title       string      `json:"title"`
	Content     string      `json:"content"`
	Status      string      `json:"status"`
	Confidence  float64     `json:"confidence"`
	SourceRefs  []SourceRef `json:"source_refs"`
	Generator   string      `json:"generator"`
	CreatedAt   time.Time   `json:"created_at"`
	UpdatedAt   time.Time   `json:"updated_at"`
}

// IDFor derives a stable memory id from its dedup key.
func IDFor(dedupKey string) string {
	h := sha256.Sum256([]byte(dedupKey))
	return "mem_" + hex.EncodeToString(h[:12])
}

// Upsert stores m (keyed by DedupKey) and indexes it for search. An existing
// memory keeps its id, creation time and status (a person may have verified
// or retracted it); content and sources are refreshed.
func Upsert(ctx context.Context, tx *sql.Tx, m *Memory, at time.Time) error {
	if m.DedupKey == "" || m.ProjectID == "" || m.Type == "" {
		return errors.New("memory: dedup key, project and type are required")
	}
	m.ID = IDFor(m.DedupKey)
	if m.Scope == "" {
		m.Scope = "project"
	}
	if m.Status == "" {
		m.Status = StatusCandidate
	}
	refs, _ := json.Marshal(m.SourceRefs)
	now := model.FormatTime(at)
	var session any
	if m.SessionID != "" {
		session = m.SessionID
	}
	if _, err := tx.ExecContext(ctx, `
		INSERT INTO memories (memory_id, project_id, session_id, dedup_key, scope, type, title, content, status,
			confidence, source_refs, generator, created_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT (dedup_key) DO UPDATE SET
			title = excluded.title, content = excluded.content, confidence = excluded.confidence,
			source_refs = excluded.source_refs, generator = excluded.generator, updated_at = excluded.updated_at
		WHERE memories.title <> excluded.title OR memories.content <> excluded.content
			OR memories.source_refs <> excluded.source_refs`,
		m.ID, m.ProjectID, session, m.DedupKey, m.Scope, m.Type, m.Title, m.Content, m.Status,
		m.Confidence, string(refs), m.Generator, now, now); err != nil {
		return fmt.Errorf("memory: store: %w", err)
	}
	sources := make([]evidence.SourceRef, 0, len(m.SourceRefs))
	for _, ref := range m.SourceRefs {
		sources = append(sources, evidence.SourceRef{Kind: ref.Kind, ID: ref.ID})
	}
	if err := evidence.RecordDerived(ctx, tx, evidence.Derived{Kind: "memory_version", Ref: m.ID, Project: m.ProjectID, Session: m.SessionID, Title: m.Title, Content: m.Content, Sources: sources, At: at}); err != nil {
		return err
	}
	return search.Upsert(ctx, tx, &search.Doc{
		Kind: search.KindMemory, RefID: m.ID, ProjectID: m.ProjectID, SessionID: m.SessionID,
		OccurredAt: at, Title: m.Title, Body: m.Content,
	})
}

// Filter selects memories.
type Filter struct {
	ProjectID string
	Type      string
	Status    string
	// Before/BeforeID page backwards from the last row of the previous page
	// (memories generated together share updated_at).
	Before   *time.Time
	BeforeID string
	Limit    int
}

const cols = `m.memory_id, m.project_id, p.name, COALESCE(m.session_id, ''), m.scope, m.type, m.title, m.content,
	m.status, m.confidence, m.source_refs, m.generator, m.created_at, m.updated_at`

func scan(sc interface{ Scan(...any) error }) (*Memory, error) {
	var m Memory
	var refs, created, updated string
	if err := sc.Scan(&m.ID, &m.ProjectID, &m.ProjectName, &m.SessionID, &m.Scope, &m.Type, &m.Title, &m.Content,
		&m.Status, &m.Confidence, &refs, &m.Generator, &created, &updated); err != nil {
		return nil, err
	}
	json.Unmarshal([]byte(refs), &m.SourceRefs)
	if m.SourceRefs == nil {
		m.SourceRefs = []SourceRef{}
	}
	m.CreatedAt, _ = time.Parse(time.RFC3339Nano, created)
	m.UpdatedAt, _ = time.Parse(time.RFC3339Nano, updated)
	return &m, nil
}

// List returns the owner's memories, most recently updated first.
func List(ctx context.Context, db *sql.DB, owner string, f Filter) ([]Memory, error) {
	where := []string{"p.user_id = ?"}
	args := []any{owner}
	for col, v := range map[string]string{"m.project_id": f.ProjectID, "m.type": f.Type, "m.status": f.Status} {
		if v != "" {
			where = append(where, col+" = ?")
			args = append(args, v)
		}
	}
	if f.Before != nil {
		b := model.FormatTime(*f.Before)
		where = append(where, "(m.updated_at < ? OR (m.updated_at = ? AND m.memory_id < ?))")
		args = append(args, b, b, f.BeforeID)
	}
	limit := f.Limit
	if limit <= 0 || limit > 200 {
		limit = 50
	}
	args = append(args, limit)
	rows, err := db.QueryContext(ctx, `SELECT `+cols+` FROM memories m JOIN projects p ON p.project_id = m.project_id
		WHERE `+strings.Join(where, " AND ")+` ORDER BY m.updated_at DESC, m.memory_id DESC LIMIT ?`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []Memory{}
	for rows.Next() {
		m, err := scan(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, *m)
	}
	return out, rows.Err()
}

// Get returns one of the owner's memories, or nil.
func Get(ctx context.Context, db *sql.DB, owner, id string) (*Memory, error) {
	m, err := scan(db.QueryRowContext(ctx, `SELECT `+cols+` FROM memories m JOIN projects p ON p.project_id = m.project_id
		WHERE m.memory_id = ? AND p.user_id = ?`, id, owner))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	return m, err
}
